const icons={arrow:'m9 5 7 7-7 7',back:'m15 5-7 7 7 7',close:'m6 6 12 12M18 6 6 18',home:'m3 10 9-7 9 7v10h-6v-7H9v7H3z',chart:'M4 20V10h3v10m4 0V4h3v16m4 0V7h3v13',device:'M5 14V9a7 7 0 0 1 14 0v5M5 11H3v8h4v-8zm14 0h2v8h-4v-8z',sun:'M12 3V1m0 22v-2M3 12H1m22 0h-2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0',scan:'M3 8V4h4m10 0h4v4M3 16v4h4m10 0h4v-4M7 12h10m-5-5v10',battery:'M3 7h16v10H3zM21 10v4M6 10h10v4H6z',wifi:'M3 8a15 15 0 0 1 18 0M6 12a10 10 0 0 1 12 0M9 16a5 5 0 0 1 6 0M12 20h0',signal:'M4 20v-4m5 4v-8m5 8V8m5 12V4',check:'m5 12 4 4 10-10',info:'M12 11v6m0-10v0M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',pause:'M8 5v14M16 5v14',play:'m8 4 12 8-12 8z',shield:'m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6zM8 11l3 3 5-5',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',settings:'M4 7h16M4 17h16M8 4v6m8 4v6',smile:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M8 9h0m8 0h0M7 14q5 6 10 0',neutral:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M8 9h0m8 0h0M8 16h8',tense:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M8 9h0m8 0h0M7 17q5-6 10 0',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M12 6v6l4 3',mail:'M3 5h18v14H3zM3 5l9 8 9-8',lock:'M6 10h12v11H6zM8 10V6a4 4 0 0 1 8 0v4',moon:'M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12',bolt:'m13 2-9 12h7l-1 8 10-13h-8z'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.info}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
icons.sound='M3 9h4l5-4v14l-5-4H3zM16 8q4 4 0 8M19 5q7 7 0 14';
icons.brain='M9 5a3 3 0 0 0-6 1v3a3 3 0 0 0 0 6v3a3 3 0 0 0 6 1m6-14a3 3 0 0 1 6 1v3a3 3 0 0 1 0 6v3a3 3 0 0 1-6 1M9 3v18m6-18v18M4 9h5m6 6h5M4 15h5m6-6h5';
icons.wave='M2 12h3l3-8 5 16 4-12 2 4h3';icons.book='M12 5v16M3 4q5-2 9 1 4-3 9-1v15q-5-2-9 2-4-4-9-2z';icons.trophy='M7 3h10v8a5 5 0 0 1-10 0zM7 5H3v4q0 4 5 4m9-8h4v4q0 4-5 4M12 16v5m-4 0h8';
const sceneData={fatigue:{title:'Fatigue check',desc:'Check in with your fatigue and choose a next step.',icon:'battery',light:12,goal:'Fatigue',headline:'A moment to reset.'},cognitive:{title:'Cognitive performance',desc:'Explore your performance on a specific task.',icon:'brain',light:8,goal:'Focus',headline:'Make space for a task.'},brain:{title:'Brain state',desc:'Observe your EEG features, with context.',icon:'wave',light:10,goal:'Relaxation',headline:'Get to know your signal.'}};
const homeDetails={
 fatigue:{time:'20 min + self-report',activity:'EEG before and after a 12-minute light session.',output:'Receive: EEG records and your fatigue ratings.'},
 cognitive:{time:'4 min + task demo',activity:'Follow the EEG check, then try a task demonstration.',output:'Receive: EEG and task-completion records; no task score.'},
 brain:{time:'4 min + optional self-report',activity:'Follow four guided eyes-open and eyes-closed periods.',output:'Receive: EEG features and signal-quality context.'}
};
const groups=[['Today & scenes',[['home','01','Today'],['plan','02','Scene plan'],['restplan','02R','Light only'],['best','12','Personal best'],['feedback','13','Guidance']]],['Check & response',[['wear','03','Headset fit'],['measure','04','EEG measurement'],['self','05','Self-report'],['task','06','Task preview'],['result','07','Your check'],['features','08','Features & quality'],['light','09','Light session'],['complete','10','Session comparison']]],['History & calibration',[['trends','11','Trends'],['history','11h','Session record'],['calibration','14','Calibration'],['learn','19','Get to know'],['science','18L','Understanding EEG']]],['Interruptions',[['invalid','15','Measurement interruption'],['held','15L','Light interruption'],['safety','16','Safety stop'],['partial','16E','Session ended'],['empty','18','First record']]],['Account & device',[['device','17','Device'],['account','A1','Account'],['profile','A2','Personal details'],['privacy','17P','Data & privacy'],['hearing','A3','Hearing setup'],['splash','00','Splash'],['welcome','00b','Welcome'],['email','00c','Email'],['password','00c1','Password'],['verify','00d','Verify email'],['forgot','00c2','Reset password'],['sent','00c3','Reset link'],['first','00e','First use'],['terms','00T','Terms & privacy']]]];
const params=new URLSearchParams(location.search),embedded=params.get('embed')==='1';
const R={screen:params.get('screen')||'home',scene:params.get('scene')||'fatigue',full:true,lightOnly:false,rest:20,phase:'before',elapsed:0,paused:false,active:false,contact:'good',connected:true,reference:false,conflict:false,rating:3,beforeRating:null,afterRating:null,beforeDone:false,afterDone:false,taskDone:false,beforeTask:false,afterTask:false,taskTaps:0,history:false,resting:false,restElapsed:0,preference:'normal',research:false,cloud:false,saved:[],modal:'',toast:'',cal:'progress',onboard:false,platform:'ios',resume:'',reason:'temperature',age:'',sex:'Prefer not to say',skin:[],hair:'Black',covered:false,email:'',privacyReturn:'device'};
if(!sceneData[R.scene])R.scene='fatigue';R.full=R.scene==='fatigue';
const contextKey='brainlume-v7-daily-context';
let previewUser='preview-local';try{previewUser=localStorage.getItem('brainlume-v7-preview-user')||('preview-'+(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)));localStorage.setItem('brainlume-v7-preview-user',previewUser)}catch{}
function localDay(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function readDaily(user=previewUser,day=R.contextDay||localDay()){try{return JSON.parse(localStorage.getItem(contextKey)||'{}')[user]?.[day]||null}catch{return null}}
function writeDaily(value){const day=R.contextDay||localDay();try{let all;try{all=JSON.parse(localStorage.getItem(contextKey)||'{}')}catch{all={}}if(!all||typeof all!=='object'||Array.isArray(all))all={};all[previewUser]??={};all[previewUser][day]={value,updatedAt:new Date().toISOString()};localStorage.setItem(contextKey,JSON.stringify(all));R.dailyDraft=all[previewUser][day];R.contextStorageError=false}catch{R.dailyDraft={value};R.contextStorageError=true}R.editSleep=false;}
function dailyContext(){return R.contextStorageError?R.dailyDraft:readDaily()||R.dailyDraft||null}
function sleepLabel(value){return ({short:'Less than 6 hours',normal:'6–8 hours',long:'More than 8 hours'})[value]||'Not recorded';}
function sleepView(){if(R.lightOnly||R.phase==='after')return '';const d=dailyContext();if(d&&!R.editSleep)return `<section class="sleep-context"><div class="section-head"><h2>Last night’s sleep</h2>${button('Change','sleep-edit','','text-link')}</div><p class="sleep-record">${sleepLabel(d.value)}</p><small>${d.value?'Recorded for today. Used as context, not an EEG conclusion.':'Skipped for today. You can add it later.'}</small>${R.contextStorageError?note('This browser could not save your daily context. It is kept only for this preview.','warning'):''}</section>`;return `<section class="sleep-context"><h2>How long did you sleep last night?</h2><p>Optional, once a day. You can change it later.</p><div class="sleep-options" role="group" aria-label="Last night’s sleep">${[['short','Less than 6 hours'],['normal','6–8 hours'],['long','More than 8 hours']].map(([v,t])=>button(t,'sleep-save',v,'secondary',`aria-pressed="${d?.value===v}"`)).join('')}</div>${button(d?'Keep current entry':'Skip today',d?'sleep-cancel':'sleep-skip','','text-link')}</section>`;}
function withDailyContext(item){const d=item.contextSaved===false||!item.previewUser||!item.contextDay?null:readDaily(item.previewUser,item.contextDay);return {...item,sleep:d?d.value:(item.sleep??null)};}
const bandExamples={A:{eo:[22,24,30,24],ec:[22,24,42,24],quality:82,n:12,chi:[1.42,1.58]},B:{eo:[18,22,38,22],ec:[17,21,56,20],quality:89,n:14,chi:null},C:{eo:[28,30,22,20],ec:[28,29,25,19],quality:76,n:10,chi:null}};
function activeBands(){const index=R.historyIndex??0;return R.bandExample&&bandExamples[R.bandExample]?bandExamples[R.bandExample]:index===2?bandExamples.C:bandExamples.A;}
function usableBands(){return R.contact!=='bad'&&!(R.history&&R.historyIndex===1);}
function bandDistribution(){const sample=activeBands(),eye=R.bandEye==='ec'?'ec':'eo',powers=sample[eye],total=powers.reduce((a,b)=>a+b,0),valid=usableBands()&&total>0;return `<section class="card band-distribution"><div class="section-head"><h2>This session’s brainwave distribution</h2><small>${R.bandExample==='B'?'Demo record B':R.historyIndex===2||R.bandExample==='C'?'Demo record C':'Demo record A'}</small></div><div class="segmented" role="group" aria-label="Eye state">${button('Eyes-open data','band-eye','eo',eye==='eo'?'selected':'',`aria-pressed="${eye==='eo'}"`)}${button('Eyes-closed data','band-eye','ec',eye==='ec'?'selected':'',`aria-pressed="${eye==='ec'}"`)}</div>${[['δ Delta','1–4 Hz'],['θ Theta','4–8 Hz'],['α Alpha','8–12 Hz'],['β Beta','12–20 Hz']].map(([name,hz],i)=>{const value=valid?(100*powers[i]/total).toFixed(1):null;return `<div class="power-band band-${i}"><div><span>${name}<small>${hz}</small></span><strong>${value===null?'—':value+'%'}</strong></div><div class="power-track" role="img" aria-label="${name.slice(2)}: ${value===null?'Not calculable':value+'% · Demo'}">${value===null?'':`<i style="width:${value}%"></i>`}</div></div>`}).join('')}<p class="caption">${valid?'Relative power: each band as a share of the four displayed bands.':'Signal quality is insufficient. No precise distribution is shown.'}</p><small class="band-source">${eye==='eo'?'Two eyes-open periods combined · Three-channel demo':'Two eyes-closed periods combined · Three-channel demo'}</small><p class="caption">Illustrative values only. Band definitions and normalization require validation.</p></section>`;}
function candidateFeatures(){const sample=activeBands(),eye=R.bandEye==='ec'?'ec':'eo',p=sample[eye],sum=p.reduce((a,b)=>a+b,0);const valid=usableBands(),ratio=(a,b)=>valid&&Number.isFinite(a)&&Number.isFinite(b)&&b>0?(a/b).toFixed(2):'Not calculable',chi=valid&&!R.fitFailed&&sample.chi;const val=chi?`${sample.chi[0].toFixed(2)} / ${sample.chi[1].toFixed(2)}`:'Not calculable';return disclosure('Calculated features · Experimental',`<p>Demo powers only. These are not validated state or ability scores.</p><p>EO = eyes open; EC = eyes closed.</p>${row('ARI · (EC α − EO α) / EO α',ratio(sample.ec[2]-sample.eo[2],sample.eo[2]))}${row('RAP · α / total',valid&&sum>0?(100*p[2]/sum).toFixed(1)+'%':'Not calculable')}${row('TLI · θ / α',ratio(p[1],p[2]))}${row('BAR · β / α',ratio(p[3],p[2]))}${row('χ EO / EC',val)}${row('Δχ · EO − EC',chi?(sample.chi[0]-sample.chi[1]).toFixed(2):'Not calculable')}<p>${!valid?'Quality is insufficient; features cannot be calculated.':R.fitFailed?'The fit failed. χ and Δχ cannot be calculated.':!sample.chi?'No fitted χ was supplied for this example.':'ARI compares absolute alpha powers. RAP, TLI and BAR follow the selected eye state.'}</p><p>Invalid denominators, insufficient quality or failed fitting show “Not calculable”. MMN is unavailable and has zero response weight.</p>`);}
function learnView(){return `<div class="learn-intro"><h1>Get to know<br>everyday brain states.</h1><p class="lead">Understand familiar experiences, without turning them into a ranking.</p></div>${[['Awake','Feeling awake and able to pay attention does not mean you have no fatigue.','sun'],['Fatigued','Mental effort can feel tiring. Fatigue and sleepiness can overlap.','battery'],['Relaxed','Feeling less tense can coexist with being awake.','smile'],['Focused','Attention is directed at a task. Understand focus alongside task performance.','brain']].map(([title,copy,i])=>`<section class="state-learning"><div>${icon(i)}<h2>${title}</h2></div><p>${copy}</p></section>`).join('')}${note('These experiences can coexist. This is not a ranking of your states, and no single EEG band directly reads these feelings.')}<div class="actions">${link('Back to Today','home')}${link('Explore EEG research & limits','science','text-link')}</div>`;}
const slug=()=>sceneData[R.scene],clock=n=>String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');
const button=(t,a='view',v='',style='primary',extra='')=>`<button class="${style}" data-a="${a}" data-v="${esc(v)}" ${extra}>${t}</button>`;
const link=(t,to,style='secondary')=>button(t,'view',to,style);
const note=(t,tone='')=>`<div class="notice ${tone}">${icon(tone==='warning'?'info':'info')}<span>${t}</span></div>`;
const row=(a,b)=>`<div class="data-row"><span>${a}</span><strong>${b}</strong></div>`;
const disclosure=(t,b,open=false)=>`<details ${open?'open':''}><summary>${t}${icon('arrow')}</summary><div>${b}</div></details>`;
const orb=(cls='')=>`<div class="photon ${cls}"><canvas width="400" height="400" aria-label="Decorative blue and violet photon sphere"></canvas></div>`;
const footer=(t,v='home')=>`<div class="actions">${link(t,v)}</div>`;
const titleOf=()=>groups.flatMap(x=>x[1]).find(x=>x[0]===R.screen)?.[2]||'Brainlume';
function go(to){if(to!=='measure')window.speechSynthesis?.cancel();R.screen=to;R.modal='';R.toast='';if(!embedded)history.replaceState(null,'',`?screen=${to}&scene=${R.scene}&theme=${R.theme}&lang=${window.BLI18n?.lang||'en'}`);render();}
function record(){return {previewUser,contextDay:R.contextDay||localDay(),contextSaved:!R.contextStorageError,sleep:dailyContext()?.value??null,scene:R.scene,lightOnly:R.lightOnly,full:R.full,beforeDone:R.beforeDone,afterDone:R.afterDone,beforeRating:R.beforeRating,afterRating:R.afterRating,beforeTask:R.beforeTask,afterTask:R.afterTask,minutes:R.lightOnly?R.rest:R.full?8+slug().light:4};}
function begin(){R.contextDay=localDay();R.editSleep=false;R.dailyDraft=null;R.beforeDone=R.afterDone=R.beforeTask=R.afterTask=false;R.beforeRating=R.afterRating=null;R.taskTaps=0;R.elapsed=0;R.phase='before';R.active=true;R.paused=false;R.contact='good';go('wear');}
function measurementDone(){if(R.contact!=='good'||!R.connected||R.paused)return;R.elapsed=240;R[R.phase==='after'?'afterDone':'beforeDone']=true;R.taskTaps=0;go(R.scene==='cognitive'?'task':'self');}
function finishCheck(rating){R[R.phase==='after'?'afterRating':'beforeRating']=rating;if(R.phase==='after'){R.active=false;R.saved.push(record());go('complete');}else{if(!R.full){R.active=false;R.saved.push(record());}go('result');}}
function endLight(){if(R.lightOnly){R.active=false;R.saved.push(record());go('complete');}else{R.phase='after';R.elapsed=0;R.paused=false;go('measure');announcePhase();}}
function phaseMessage(){return [
 'Period 1 of 4. Keep your eyes open and look ahead.',
 'Period 2 of 4. Close your eyes and rest comfortably.',
 'Period 3 of 4. Keep your eyes closed. One minute remains before opening.',
 'Period 4 of 4. Open your eyes and look ahead.'
][Math.min(3,Math.floor(R.elapsed/60))];}
function announcePhase(test=false){
 const message=window.BLI18n?.t(test?'This is a voice preview. Follow the spoken eyes-open and eyes-closed guidance.':phaseMessage())||phaseMessage();
 const live=document.getElementById('phase-announcement');if(live)live.textContent=message;
 if(embedded||document.hidden||(!R.phaseCues&&!test)||!('speechSynthesis' in window)||!('SpeechSynthesisUtterance' in window))return;
 window.speechSynthesis.cancel();const speech=new SpeechSynthesisUtterance(message);speech.lang=window.BLI18n?.lang==='zh'?'zh-CN':'en-US';speech.rate=.95;speech.onerror=e=>{if(!['canceled','interrupted'].includes(e.error))toast('Voice could not play. Use the screen instructions.');};try{window.speechSynthesis.speak(speech)}catch{toast('Voice could not play. Use the screen instructions.');}
}
function guidanceControls(){return `<section class="phase-guidance"><h2>Before you begin</h2><p>Four periods, 60 seconds each: open, closed, closed, open. Stay awake and keep your headset in place.</p><div class="cue-choice">${button(`${icon('sound')}<span>Spoken phase cues</span><strong>${R.phaseCues?'On':'Off'}</strong>`,'phase-cues','','secondary',`aria-pressed="${!!R.phaseCues}"`)}${button('Try voice','cue-test','','text-link','speechSynthesis' in window?'':'disabled')}</div><small>${'speechSynthesis' in window?'Try the voice before starting. Screen instructions remain available.':'Voice is unavailable in this browser. Use the screen instructions.'}</small></section>`;}
function chips(){return `<div class="periods" aria-label="Four 60-second periods">${['Open','Closed','Closed','Open'].map((x,i)=>`<div class="${i===Math.min(3,Math.floor(R.elapsed/60))?'on':i<Math.floor(R.elapsed/60)?'done':''}"><i></i><span>${x}</span></div>`).join('')}</div>`;}
function eeg(){return `<section class="eeg"><div class="section-head"><h2>EEG signals</h2><small>Simulated signal</small></div>${[1,2,3].map(c=>`<div class="channel ch${c}"><div class="channel-label"><strong>${R.screen==='wear'?['Fp1','Fpz','Fp2'][c-1]:'CH'+c}</strong><span>${!R.connected?'Disconnected':R.contact==='bad'&&c===2?'Adjust contact':'Good contact'} · <b data-value="${c}">—</b> µV</span></div><svg viewBox="0 0 310 70" role="img" aria-label="Channel ${c} simulated EEG"><path class="grid" d="M0 15H310M0 35H310M0 55H310"/><path data-wave="${c}" class="trace" d="M0 35H310"/></svg></div>`).join('')}<div class="axis"><span>−4 s</span><span>−2 s</span><span>Now</span></div></section>`;}

function sceneHome(){
 const scenes=[
 ['fatigue','battery','Fatigue check','Observe fatigue against your own records.','20 min + self-report','scene'],
 ['cognitive','brain','Cognitive performance','Explore performance on a specific task.','4 min + task demo','scene'],
 ['brain','wave','Brain state','View EEG features and collection quality.','4 min + optional self-report','scene'],
 ['best','trophy','Personal best','Prepare for a task with your own reference.','Comparable records needed','view'],
 ['feedback','smile','Guidance','Choose a practical next step, at your pace.','About 3 minutes','view']
 ];
 return `<section class="ue-home-greeting">${orb()}<p class="home-welcome">Hello, welcome back.</p><h1>Do you feel awake right now?</h1><div class="awake-checkin" role="group" aria-label="How awake you feel">${[['awake','Awake'],['sleepy','A little sleepy'],['unsure','Not sure']].map(([v,t])=>button(t,'awake',v,'awake-option',`aria-pressed="${R.awakeFeeling===v}"`)).join('')}</div><p class="caption" role="status">${R.awakeFeeling?'Thanks for sharing. Choose any scene below.':'Start with a feeling, or go straight to a scene.'}</p></section>
 ${R.active?`<section class="resume-card">${row('Session paused','Your completed stages are saved')}${button('Continue session','resume')}</section>`:''}
 <section class="ue-scene-section"><div class="section-head"><h2>What brings you here?</h2><small>Choose a purpose</small></div><div class="ue-scene-list">${scenes.map(([id,i,t,d,time,action])=>button(`${icon(i)}<span><strong>${t}</strong><small>${d}</small><em>${time}</em></span>${icon('arrow')}`,action,id,'ue-scene-row')).join('')}</div></section>
 <div class="ue-shortcuts">${button(`${icon('scan')}<span><strong>Daily check</strong><small>4 min · No light</small></span>`,'quick','','secondary')}${button(`${icon('sun')}<span><strong>Light only</strong><small>10 / 20 / 30 min</small></span>`,'rest','','secondary')}</div>
 ${button(`<span><strong>Everyday brain states</strong><small>Explore being awake, fatigued, relaxed and focused.</small></span>${icon('arrow')}`,'view','learn','learn-entry')}`;
}
function sessionRoute(){
 if(!R.full||R.lightOnly||!['wear','measure','self','task','result','light'].includes(R.screen))return '';
 const active=R.screen==='light'?1:R.phase==='after'?2:0;
 return `<ol class="ue-session-route" aria-label="Session stages">${[['Before','4 min'],['Light Session',slug().light+' min'],['After','4 min']].map(([t,time],i)=>`<li class="${i===active?'current':i<active?'finished':''}" ${i===active?'aria-current="step"':''}><span>${i<active?icon('check'):i+1}</span><div><strong>${t}</strong><small>${time}</small></div></li>`).join('')}</ol>`;
}
function nextStepView(){return `<section class="ue-next-step"><h2>Your next step</h2><p>${R.contact==='bad'?'Adjust the fit and repeat all four periods.':R.full&&R.beforeDone?'Your Before record is saved. Continue when you are ready.':'Keep this record, or take a short break.'}</p><div class="actions">${R.contact==='bad'?button('Check fit & restart','restart'):R.full&&R.beforeDone?button(`Continue to ${slug().light}-minute light`,'start-light'):link('Review rest suggestions','feedback')}${button('View session record','current-record','','secondary')}</div></section>`;}

function main(){switch(R.screen){
case'home':return sceneHome();
case'plan':return `<h1>${slug().headline}</h1><p class="lead">${slug().desc}</p><div class="segmented" role="group" aria-label="Session mode">${(R.scene==='fatigue'?[true,false]:[false,true]).map(full=>button(full?'Check + light':R.scene==='cognitive'?'Assess only':'Check only','mode',String(full),R.full===full?'selected':'',`aria-pressed="${R.full===full}"`)).join('')}</div><section class="ue-plan-total"><div>${icon('clock')}<strong>${R.full?8+slug().light:4}<small> min</small></strong></div><p>${R.scene==='cognitive'?'Task time is additional.':'Self-report time is additional.'}</p></section><ol class="phase-list">${(R.full?[[R.scene==='cognitive'?'Before check + task':'Before check (4 min)','Record your starting point.'],[`${slug().goal} light (${slug().light} min)`,'Rest comfortably. No effort needed.'],[R.scene==='cognitive'?'After check + task':'After check (4 min)','Repeat the same protocol.']]:[['EEG check (4 min)','Follow the eyes-open and eyes-closed guidance.'],[R.scene==='cognitive'?'A specific task':'Your experience',R.scene==='cognitive'?'Task specification is being finalized.':'Add a self-report, or skip it.'],['Your record','See the sources and their limits.']]).map(([a,b])=>`<li><strong>${a}</strong><p>${b}</p></li>`).join('')}</ol><div class="actions">${button('Check headset fit','begin')}${disclosure('About this session','<p>Light settings depend on personal calibration. Before and After must use matching protocols. Changes describe an observation and do not establish an effect of light.</p><p>This interactive preview uses simulated device data and does not perform a real assessment.</p>')}</div>`;
case'restplan':return `<h1>Time without<br>a task.</h1><p class="lead">A light session on its own. No EEG check, no before-and-after score.</p>${orb()}<div class="section-head"><h2>Choose your time</h2></div><div class="segmented">${[10,20,30].map(n=>button(n+' min','rest-duration',String(n),R.rest===n?'selected':'',`aria-pressed="${R.rest===n}"`)).join('')}</div>${note('Intensity follows the validated device setting. This preview does not select or control a light dose.')}<div class="actions">${button('Check headset fit','begin')}${link('Back to Today','home','text-link')}</div>`;
case'wear':return `<h1>A comfortable fit.<br>A clearer signal.</h1><p class="lead">Sit comfortably, relax your forehead and keep hair clear of the contacts.</p>${R.lightOnly?'':`<section class="wear-signals">${eeg()}${button(R.wearWavePaused?'Resume wave preview':'Pause wave preview','wear-waves','','text-link',`aria-pressed="${!!R.wearWavePaused}"`)}<p class="caption">Reduce blinking, jaw clenching and head movement. Contact is confirmed by device quality checks.</p></section>`}${note(!R.connected?'Reconnect your headset to continue.':R.contact==='bad'?'Adjust the center contact and check again.':'Keep a supported position throughout the session.',R.contact==='bad'||!R.connected?'warning':'')}${sleepView()}${disclosure('Headset fit guide',`<img class="product product-lifestyle" src="assets/product-worn-model-20261113.png" alt="Model wearing the Brainlume headset"><div class="fit-list">${['Fp1','Fpz','Fp2'].map((n,i)=>row(n,(!R.connected?'Disconnected':R.contact==='bad'&&i===1?'Adjust contact':'Contact ready')+icon(R.contact==='bad'&&i===1?'info':'check'))).join('')}</div>`)}${R.lightOnly?'':guidanceControls()}<div class="actions">${!R.connected?button('Reconnect · Demo','fix'):R.contact==='bad'?button('I’ve adjusted the fit','fix'):button(R.lightOnly?'Start light session':'Start measurement','record')}${button('End session','end','','secondary')}</div>`;
case'measure':{const part=Math.min(3,Math.floor(R.elapsed/60));return `${R.full?`<p class="session-stage">${R.phase==='after'?'After check':'Before check'} · ${slug().title}</p>`:''}${chips()}<div class="measurement-heading"><div><h1>${[0,3].includes(part)?'Eyes open':'Eyes closed'}</h1><p>${[0,3].includes(part)?'Rest your gaze ahead.':'Stay comfortable. Let your eyes rest.'}</p></div><div class="period-time"><strong id="period-clock">${clock(R.elapsed%60)}</strong><small>/ 01:00</small></div></div><p class="phase-next">${part===0?'Next: close your eyes.':part===1?'Next: keep your eyes closed.':part===2?'Next: open your eyes.':R.scene==='cognitive'?'Final period. Your task comes next.':'Final period. Your check-in comes next.'}</p>${eeg()}${button(`${icon('sound')} ${R.phaseCues?'Voice cues on':'Voice cues off'}`,'phase-cues','','text-link measurement-voice',`aria-pressed="${!!R.phaseCues}"`)}<p class="signal-caption">${R.paused?'Paused · No new samples are added.':!R.connected?'Disconnected · Recording held.':R.contact==='bad'?'Poor contact · Recording held.':'Illustrative waveforms · Not a live EEG reading.'}</p>${R.paused?note('Resume to continue this period. A contact interruption requires a fresh four-period measurement.'):''}<div class="measurement-actions">${button(`${icon(R.paused?'play':'pause')} ${R.paused?'Resume':'Pause'}`,'pause','','primary')}${button('End session','end','','secondary')}</div><small class="usable" id="usable">${clock(Math.max(0,R.elapsed-Math.ceil(R.elapsed/60)*4))} usable signal · Period ${part+1} of 4</small>${disclosure('About this measurement','<p>Each period lasts 60 seconds. Open → Closed → Closed → Open. Quality thresholds and transition windows are pending protocol confirmation.</p><p>Passive auditory / MMN output is unavailable pending validation. This prototype plays no tones.</p>')}`;}
case'self':return `<h1>How does this<br>moment feel?</h1><p class="lead">${R.phase==='after'?'After your session':'Before moving on'}, record your own experience.</p><div class="rating-card"><h2>Your fatigue rating</h2><div class="rating-value"><strong id="rating-number">${R.rating}</strong><span>/ 5</span></div><input type="range" min="1" max="5" value="${R.rating}" data-field="rating" aria-label="Fatigue rating"><div class="range-labels"><span>Not tired</span><span>Very tired</span></div><small>Self-reported · Optional</small></div><div class="actions">${button('Save my check-in','rating-save')}${button('Skip for now','rating-skip','','secondary')}</div>`;
case'task':return `<h1>One task.<br>Its own result.</h1><p class="lead">A behavioral task provides a separate view from your EEG.</p><div class="task-preview"><span>Task preview</span><strong>${R.taskTaps} / 3</strong>${button(R.taskTaps<3?'Tap target':'Preview complete','task-tap','','secondary',R.taskTaps>=3?'disabled':'')}</div>${note('These three taps demonstrate the flow only. They are not a cognitive test and do not generate accuracy or reaction-time scores.')}<div class="actions">${button('Continue to record','task-done','','primary',R.taskTaps<3?'disabled':'')}${button('End assessment','end','','secondary')}</div>`;
case'result':return resultView();
case'features':return `<h1>Your brainwaves & quality.</h1><p class="lead">Compare the distribution across eyes-open and eyes-closed periods.</p>${bandDistribution()}<p class="caption">Forehead channels · 1–20 Hz. No Gamma band or scalp topography.</p><section class="card"><h2>Collection quality</h2>${row('Usable data',usableBands()?activeBands().quality+'% · Demo':'Not usable')}${row('Common valid segments',usableBands()?'N = '+activeBands().n+' · Demo':'Not available')}${row('Channels','Fp1 / Fpz / Fp2')}${row('Device bandwidth','1–20 Hz · UE proposal')}<p class="caption">Example quality values are not acceptance thresholds.</p></section>${candidateFeatures()}${disclosure('Collection & calculation notes','<p>Open → Closed → Closed → Open, 60 seconds each. Eye and forehead muscle activity can affect these signals.</p><p>Band boundaries, transition windows, quality gates and primary response direction await validation.</p>')}${disclosure('Versions & comparability',row('Protocol','EO–EC–EC–EO · Draft')+row('Device / firmware','Brainlume · Demo firmware')+row('Algorithm / metrics','Unvalidated · Demo version')+row('Task version','Not supplied')+'<p>Different conditions may exclude a record from comparison.</p>')}${footer('Back to your record',R.history?'history':'result')}`;
case'light':{const seconds=(R.lightOnly?R.rest:slug().light)*60;return `<p class="session-stage">${R.lightOnly?'Light only':slug().goal+' light · Between checks'}</p><h1>Give yourself<br>a little space.</h1><p class="lead">Rest comfortably. Breathe naturally.</p><div class="light-orbit">${orb('large')}<div><strong id="light-clock">${clock(Math.max(0,seconds-R.elapsed))}</strong><span>${R.paused?'Paused':'Time remaining · Demo'}</span></div></div><div class="light-checks">${row('Temperature','Monitoring · Demo')}${row('Cumulative energy','Within demo limit')}${row('Driver current','Normal · Demo')}</div><p class="caption">${R.lightOnly?'No EEG is collected in this light-only session.':'EEG collection during light is pending review; no light-stage EEG is used in this preview.'}</p><div class="measurement-actions">${button(R.paused?'Resume':'Pause','pause','','primary')}${button('End session','end','','secondary')}</div>${disclosure('About this session','<p>Intensity is not adjusted here. Real light output, wear detection and safety stops require device confirmation. This is a simulated timer, not a device controller.</p>')}`;}
case'complete':return completeView();
case'trends':return `<h1>Your patterns,<br>over time.</h1><p class="lead">Compare like with like. Keep the context.</p><div class="segmented">${button('7 days','range','7',!R.range||R.range===7?'selected':'')}${button('30 days','range','30',R.range===30?'selected':'')}</div>${R.empty?emptyCard():`<section class="card"><div class="section-head"><h2>Your check-ins</h2><small>Self-reported</small></div>${trendChart()}<p class="caption">Example ratings · Gap = different protocol. Missing data is not interpolated.</p></section>${row('Included / recorded','8 / 11 · Example')}<div class="section-head"><h2>Recent records</h2></div>${[['Today, 09:41',R.saved.length?'Your preview session':'Fatigue check · Example'],['Yesterday, 18:20','Light only · 20 min'],['Nov 6, 08:30','Excluded · Different protocol']].map(([a,b],i)=>button(`<span><strong>${a}</strong><small>${b}</small></span>${icon('arrow')}`,'history',String(i),'list-button')).join('')}`}${link('Your personal calibration','calibration','list-button')}${link('Explore personal best','best','text-link')}`;
case'history':return `<h1>Your session<br>record.</h1><p class="lead">${R.historyIndex===1?'Light only · 20 min':R.historyIndex===2?'Nov 6 · Excluded from comparison':'Today · '+slug().title}</p>${R.historyIndex===2?note('This record uses a different protocol version. It is kept as an individual record and excluded from the trend.','warning'):note('Preview record · This is not a clinical assessment.')}${row('Status',R.historyIndex===2?'Not comparable':'Recorded')}${row('EEG',R.historyIndex===1?'Not collected':'Four 60-second periods')}${row('Task result',R.historyIndex===1?'Not applicable':'Not available')}${row('Last night’s sleep',sleepLabel(withDailyContext(R.currentRecord||(R.historyIndex===0?R.saved.at(-1):null)||{sleep:null}).sleep))}${row('Sync','Saved in preview memory')}<div class="actions">${R.historyIndex!==1?link('Features & quality','features'):''}${button('Export sample record','export','','secondary')}${link('Back to Trends','trends','text-link')}</div>`;
case'best':return `<h1>Find a reference<br>that’s yours.</h1><p class="lead">Look for patterns around the same task and goal, across your own records.</p><section class="card"><h2>Your next task</h2><label>What matters most?<select data-field="bestGoal"><option>More consistent responses</option><option>More accurate answers</option></select></label><p class="caption">The formal task and scoring protocol are still being finalized.</p></section><div class="empty-graphic">${icon('trophy')}</div><h2>More comparable records needed.</h2><p class="lead">There isn’t a reliable personal-best reference yet. No readiness score or best brainwave value is shown.</p>${disclosure('How the reference will work','<p>Choose a task and goal, identify stronger performances on the same task, then observe associated EEG features and context. Validate those patterns in new sessions.</p><p>Sleep, time of day, difficulty and practice matter. Association does not establish cause.</p>')}<div class="actions">${button('Start a task assessment','best-assess')}${link('See your records','trends','secondary')}</div>`;
case'feedback':return feedbackView();
case'calibration':return calibrationView();
case'invalid':return `<div class="state-symbol">${icon('info')}</div><h1>Let’s get a<br>clearer signal.</h1><p class="lead">${!R.connected?'Bluetooth disconnected.':'Contact quality was interrupted.'} This four-period measurement is incomplete.</p>${row('Completed Before check',R.beforeDone?'Saved':'Not available')}${row('Current measurement','No usable result')}${note('Restart the entire current four-period measurement after checking the fit. Missing segments will not be filled in.','warning')}<div class="actions">${button('Check fit & restart','restart')}${link('Review device','device','secondary')}${button('End session','end','','text-link')}</div>`;
case'held':return `<div class="state-symbol">${icon('shield')}</div><h1>Your comparison<br>is on hold.</h1><p class="lead">The light session was interrupted by a disconnect or headset removal.</p>${row('Before check',R.beforeDone?'Saved':'Not collected')}${row('Light stage','Interrupted')}${row('After response','Not generated')}${note('The final handling of light-stage disconnects and removal is pending protocol review. Completed data stays in the record.','warning')}<div class="actions">${link('Review device','device')}${button('Save & return to Today','safe-home','','secondary')}</div>`;
case'safety':return `<div class="state-symbol">${icon('shield')}</div><h1>Stopped to<br>keep you safe.</h1><p class="lead">${({temperature:'Temperature limit',energy:'Cumulative energy limit',current:'Driver current limit',user:'You chose to stop'})[R.reason]} · Simulated event.</p>${note('Light and sound are off in this preview. Real hardware must independently confirm the stop.','warning')}${row('Before check',R.beforeDone?'Saved':'Not available')}${row('Session comparison','Unavailable')}<div class="actions">${button('Save & return to Today','safe-home')}${link('Review device','device','secondary')}</div>`;
case'partial':return `<div class="state-symbol">${icon('check')}</div><h1>This session<br>has ended.</h1><p class="lead">Your completed stages are saved. An incomplete session has no before-and-after conclusion.</p>${row('Before check',R.beforeDone?'Saved':'Not completed')}${row('After check',R.afterDone?'Saved':'Not completed')}${footer('Back to Today')}`;
case'empty':return `<h1>Your first record<br>starts here.</h1>${emptyCard()}${footer('Choose a check','home')}`;
case'learn':return learnView();
case'science':return scienceView();
case'device':return `<h1>Ready when<br>you are.</h1><img class="product product-lifestyle" src="assets/product-worn-model-20261113.png" alt="Model wearing the Brainlume headset"><section class="card">${row('Brainlume headset',R.connected?'Connected · Demo':'Offline')}${row('Battery',R.connected?'86% · Demo':'Unavailable')}${row('Signal contacts',R.contact==='bad'?'Needs adjustment':'Check before each measurement')}${row('Light safety','Device confirmation required')}</section><div class="section-head"><h2>Your space</h2></div>${[['profile','Personal details','Sensor conditions and fit'],['calibration','Light calibration','Progress and review outcomes'],['hearing','Hearing setup','Protocol review pending'],['account','Account','Preview account'],['privacy','Data & privacy','Your controls']].map(([id,t,d])=>link(`<span><strong>${t}</strong><small>${d}</small></span>${icon('arrow')}`,id,'list-button')).join('')}${button(R.connected?'Disconnect demo device':'Reconnect demo device','device-toggle','','secondary')}`;
case'account':return `<h1>Your personal<br>space.</h1><div class="avatar">A</div>${row('Email','alex@example.com')}${row('Account','Preview only')}<div class="actions">${link('Personal details','profile')}${link('Data & privacy','privacy','secondary')}${link('Reset password','forgot','secondary')}${link('Sign out of preview','welcome','text-link')}</div>`;
case'profile':return profileView();
case'privacy':return `<h1>Your data.<br>Your choice.</h1><p class="lead">Daily use and research participation are separate choices.</p>${toggle('research','Research participation','Optional, separate consent. Declining does not affect daily use.')}${toggle('cloud','Cloud sync preference','A preview preference only. No files are uploaded.')}<section class="card"><h2>Save before syncing</h2><p>A completed session should be saved locally before a user chooses to sync. Session records stay in preview memory. Optional daily sleep context stays in this browser only.</p></section>${button('Sync preview record','sync','','secondary')}${button('Export sample record','export','','secondary')}${button('Delete preview records','delete','','secondary')}${button('Withdraw research preference','withdraw','','text-link')}${link('Privacy information','terms','list-button')}${R.onboard?button('Continue to device setup','activate-next'):footer('Back to Device','device')}`;
case'hearing':return `<h1>Sound, kept<br>in perspective.</h1><div class="sound-bars" aria-hidden="true">${Array.from({length:15},(_,i)=>`<i style="height:${14+45*Math.sin(i/14*Math.PI)}px"></i>`).join('')}</div><p class="lead">A passive auditory protocol may use tones alongside EEG. You don’t need to count or react to those tones.</p>${note('Hearing thresholds, sound limits and forehead MMN suitability are awaiting validation. No sound or MMN score is generated in V7.')}<div class="actions">${R.onboard?link('Continue to data preferences','privacy'):link('Back to Device','device')}</div>`;
case'splash':return `<div class="splash">${orb('large')}<img src="assets/Brainlume-logo-white.png" alt="Brainlume"><p>A moment for your mind.</p>${link('Begin','welcome')}</div>`;
case'welcome':return `<section class="welcome-content"><h1><span>Understand.</span> <span>Pause.</span><br>Begin again.</h1><p class="lead">A quiet space to check in, explore your patterns and take a guided pause.</p><div class="actions">${link('Get started','email','primary')}${link('Explore the preview','home','secondary')}</div></section>`;
case'email':return `<h1>A space<br>of your own.</h1><p class="lead">Create or access your Brainlume account.</p><form data-form="email"><label>Email<input type="email" name="email" autocomplete="off" required placeholder="you@example.com" value="${esc(R.email)}"></label><p class="caption">Use a sample address in this preview. Nothing is sent.</p><button class="primary" type="submit">Continue</button></form>${link('Terms & privacy','terms','text-link')}`;
case'password':return `<h1>Keep your<br>space private.</h1><form data-form="password"><label>Password<input type="password" name="password" minlength="8" required autocomplete="new-password" placeholder="At least 8 characters"></label><p class="caption">Demo only. Your password is not saved or transmitted.</p><button class="primary" type="submit">Continue preview</button></form>${link('Forgot password?','forgot','text-link')}`;
case'verify':return `<div class="state-symbol">${icon('mail')}</div><h1>Check your<br>inbox.</h1><p class="lead">In the real app, you would verify ${esc(R.email||'your email address')}.</p>${note('No email was sent by this preview.')}<div class="actions">${link('Simulate verification','first')}${button('Resend demo link','resend','','secondary')}</div>`;
case'forgot':return `<h1>A fresh<br>start.</h1><p class="lead">Request a password reset link.</p><form data-form="reset"><label>Email<input type="email" name="email" required placeholder="you@example.com"></label><button class="primary" type="submit">Preview reset request</button></form>`;
case'sent':return `<div class="state-symbol">${icon('mail')}</div><h1>Your next step<br>is in your inbox.</h1>${note('Reset request preview complete. No message was sent.')}<div class="actions">${link('Back to sign in','email')}</div>`;
case'first':return `<h1>Start with<br>your own context.</h1><p class="lead">Your first check records this moment. Comparisons appear only when suitable personal reference data exists.</p>${note('No previous records means no rise-or-fall conclusion. Your record can still include self-report, quality and EEG features.')}<div class="actions">${button('Set up my details','setup')}${link('Explore Today','home','secondary')}</div>`;
case'terms':return `<h1>Clear choices.<br>Clear boundaries.</h1><section class="card"><h2>Preview information</h2><p>This prototype does not create an account or process real health data. All device signals and sample records are illustrative.</p><h2>Production policy required</h2><p>The final terms and privacy notice must explain purposes, retention, access, transfers, export, deletion and withdrawal. Legal text has not been supplied.</p></section>${footer('Back',R.onboard?'privacy':'account')}`;
default:return `<h1>Choose your<br>starting point.</h1>${footer('Back to Today')}`;
}}
function recordSummary(completed=false){
 const bad=R.contact==='bad',cognitive=R.scene==='cognitive';
 const status=bad?'Signal incomplete':completed?(R.lightOnly?'Light session recorded':R.beforeDone&&R.afterDone?'Before and After recorded':'Some stages are missing'):R.beforeDone?'Before check recorded':'Example record';
 const explanation=bad?'Some signal could not be used. No state conclusion is shown.':R.lightOnly?'This session has no EEG check or response score.':cognitive?'Task completion and EEG are separate records. The demo does not calculate task scores.':R.scene==='brain'?'Your EEG record includes quality and protocol context. No brain-state score is calculated.':'Your fatigue rating records how you felt. It is separate from the EEG record.';
 return `<section class="record-summary" aria-label="Record summary"><div class="summary-status">${icon(bad?'info':'check')}<h2>${status}</h2></div><p>${explanation}</p><dl><div><dt>Signal quality</dt><dd>${R.lightOnly?'Not collected':bad?'Not usable':R.beforeDone?'Usable · Example':'Example only'}</dd></div><div><dt>${cognitive?'Task score':'Self-report'}</dt><dd>${cognitive?'Not available':R.lightOnly?'Not collected':R.beforeRating===null?'Not recorded':'Recorded separately'}</dd></div><div><dt>Personal comparison</dt><dd>${R.lightOnly?'Not applicable':R.conflict?'Sources differ':R.reference?'Matching conditions required':'No comparable reference yet'}</dd></div></dl><p class="summary-limit">${R.conflict?'The sources do not agree clearly. No single conclusion is drawn.':R.lightOnly?'A comfort note can be kept separately.':R.reference?'A reference does not establish a validated state estimate.':'This record can be saved without a personal comparison.'}</p></section>`;
}
function resultView(){const rat=R.beforeRating;const evidence=R.scene==='cognitive'?`<section class="card"><h2>Your task record</h2>${row('Task preview',R.beforeTask?'Completed':'Not completed')}${row('Accuracy','Not available')}${row('Median reaction time','Not available')}${row('CV(RT)','Not available')}${row('Omission rate','Not available')}${row('Scorable trials / difficulty','Not supplied')}${row('Task version','Not supplied')}<p class="caption">The formal task and scoring are pending. Demo taps do not generate a cognitive score.</p></section>`:`<section class="rating-summary ${R.scene==='brain'?'supporting-rating':''}"><div><h2>${R.scene==='brain'?'Fatigue as context':'Your fatigue rating'}</h2><p>Self-reported</p></div><strong>${rat===null?'—':rat+' <small>/ 5</small>'}</strong></section>${rat===null?'<p class="caption">Self-report not recorded.</p>':''}`;return `<h1>${R.contact==='bad'?'A clearer signal<br>is needed.':R.conflict?'Let’s keep<br>the context.':R.scene==='cognitive'?'Your task,<br>in context.':R.scene==='brain'?'Your signal,<br>with context.':'A record of<br>this moment.'}</h1><p class="lead">${slug().title} · ${R.beforeDone?'Before check recorded':'Illustrative record'}</p>${R.contact==='bad'?note('Quality is insufficient. No state estimate is generated.','warning'):R.conflict?note('The sources do not agree clearly. No single conclusion is drawn.','warning'):''}${recordSummary()}${nextStepView()}${R.scene==='brain'?bandDistribution()+evidence:evidence+bandDistribution()}${disclosure('EEG features','<p>Signal features can be viewed with their quality and protocol. They are not a mental-state diagnosis.</p>'+link('View features & quality','features','secondary'))}`;}
function completeView(){return `<div class="state-symbol success">${icon('check')}</div><h1>${R.lightOnly?'A pause,<br>recorded.':'Your session,<br>in context.'}</h1><p class="lead">${R.lightOnly?'Light only · '+R.rest+' minutes':slug().title+' · Before and After'}</p>${recordSummary(true)}${R.lightOnly?`<section class="card">${row('EEG','Not collected')}${row('Response score','Not applicable')}${row('Session','Light only')}<p class="caption">This record does not enter EEG trends or dose-response curves.</p></section>`:`<section class="card"><div class="compare-row heading"><span>Source</span><span>Before</span><span>After</span></div><div class="compare-row"><span>EEG check</span><strong>${R.beforeDone?'Saved':'—'}</strong><strong>${R.afterDone?'Saved':'—'}</strong></div>${R.scene==='cognitive'?`<div class="compare-row"><span>Task preview</span><strong>${R.beforeTask?'Done':'—'}</strong><strong>${R.afterTask?'Done':'—'}</strong></div><p class="caption">No task scores are computed by this preview.</p>`:`<div class="compare-row"><span>Fatigue rating</span><strong>${R.beforeRating??'—'}${R.beforeRating!==null?' / 5':''}</strong><strong>${R.afterRating??'—'}${R.afterRating!==null?' / 5':''}</strong></div><p class="caption">Same self-report scale · Missing values stay unrecorded.</p>`}</section>`}${note(R.lightOnly?'You can add a comfort note. No EEG improvement is inferred.':'Before-and-after changes are observations. They do not establish an effect of light.')}<div class="actions">${link('Choose a next step','feedback')}${button('View session record','current-record','','secondary')}${link('Back to Today','home','text-link')}</div>`;}
function feedbackView(){if(R.resting)return `<h1>Space to<br>simply be.</h1><p class="lead">Set your task aside and breathe naturally.</p><div class="rest-clock" id="rest-clock">${clock(Math.max(0,180-R.restElapsed))}</div><p class="caption">About 3 minutes. You can finish at any time.</p><div class="actions">${button('Finish resting','rest-finish')}</div>`;return `<h1>${R.dismissed?'Continue at<br>your own pace.':R.restFinished?'Take the next step<br>at your pace.':'A short pause,<br>if it suits you.'}</h1><p class="lead">${R.dismissed?'This suggestion is dismissed for this session.':R.restFinished?'Your rest is complete. You can return to your day or rest a little longer.':'You can choose to rest now, or keep going.'}</p>${!R.restFinished&&!R.dismissed?`<section class="card"><h2>Take a short rest</h2><p>Put your task aside. No device or light is needed.</p><div class="duration-small">${icon('clock')} About 3 minutes</div></section><p class="caption">A general rest option, not an EEG-based prescription.</p>`:''}<div class="actions">${button(R.restFinished?'Rest a little longer':'Start resting','rest-start')}${R.restFinished||R.dismissed?link('Back to Today','home','secondary'):button('Not now','rest-dismiss','','secondary')}</div>${disclosure('Adjust rest reminders',`<p>${R.preference==='off'?'Reminders are off.':R.preference==='less'?'Fewer reminders selected.':'You stay in control of suggestions.'}</p>${button('Suggest less often','reminders','less','secondary')}${button('Turn reminders off','reminders','off','text-link')}`)}`;}
function calibrationView(){if(['uncertain','insufficient','none'].includes(R.cal))return `<h1>${R.cal==='insufficient'?'Not enough<br>usable data.':R.cal==='none'?'No clear<br>response found.':'No reliable<br>setting yet.'}</h1><p class="lead">This round has ended without a confirmed personal setting.</p>${row('Attempts','10 / 10 · Example')}${row('Personal setting','Not determined')}${note('No automatic dose increase. An invalid session is not a zero response.','warning')}<div class="actions">${link('Review fit','wear')}${link('Back to Trends','trends','secondary')}</div>`;return `<h1>${R.cal==='done'?'Your calibration,<br>ready for review.':'Learn what<br>fits you.'}</h1><p class="lead">A series of sessions, not one reading.</p><div class="duration"><strong>${R.cal==='done'?'6':'4'}<small> / 6</small></strong><p>Initial sessions · Example</p></div><div class="cal-dots">${Array.from({length:6},(_,i)=>`<i class="${i<4?'done':''}">${i<4?icon('check'):i+1}</i>`).join('')}</div>${note(R.cal==='done'?'Completion requires protocol review and separate evaluation. This preview does not compute a personal dose.':'Individual dose and response values stay hidden until the calibration series is complete.')}<section class="card">${row('Initial sequence','6 fixed sessions')}${row('Control','At least one sham condition')}${row('Maximum attempts','10 · Proposal')}${row('Per-condition repeat','At most once')}</section>${disclosure('When the process stops','<p>Six sessions do not automatically establish a reliable setting. Further attempts follow a predefined review within the limit.</p><p>Missing valid conditions lead to insufficient data; an uncertain peak leads to an uncertain result. Stop thresholds and the main response remain pending validation.</p>')}<div class="actions">${link('Back to Trends','trends')}</div>`;}
function emptyCard(){return `<div class="empty-graphic">${icon('chart')}</div><h2>No comparable records yet.</h2><p class="lead">Start with one record. A personal reference needs matching protocols and suitable data.</p>`;}
function trendChart(){return `<svg class="trend-chart" viewBox="0 0 310 150" role="img" aria-label="Illustrative self-reported fatigue ratings, with a gap for an excluded record"><g class="chart-grid"><path d="M24 20H295M24 65H295M24 110H295"/></g><rect x="24" y="50" width="271" height="40" class="reference-band"/><path class="chart-line" d="M24 92L68 72L112 81 M203 63L250 52L294 68"/>${[[24,92],[68,72],[112,81],[203,63],[250,52],[294,68]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="4"/>`).join('')}<g class="chart-labels"><text x="24" y="140">Nov 2</text><text x="132" y="140">Nov 6</text><text x="263" y="140">Nov 9</text></g></svg>`;}
function toggle(key,t,d){return `<div class="toggle-row"><div><strong>${t}</strong><p>${d}</p></div><button class="switch ${R[key]?'on':''}" role="switch" aria-checked="${R[key]}" aria-label="${t}" data-a="toggle" data-v="${key}"><i></i></button></div>`;}
function profileView(){return `<h1>A better fit<br>for your signal.</h1><p class="lead">These details describe sensor conditions. They are not used here to identify you.</p><form data-form="profile"><label>Age<input type="number" name="age" min="18" max="110" value="${esc(R.age)}" placeholder="Your age"></label><label>Sex<select data-field="sex">${['Prefer not to say','Female','Male','Other'].map(x=>`<option ${R.sex===x?'selected':''}>${x}</option>`).join('')}</select></label><div class="field"><span>Skin tone</span><div class="swatches">${['#f0d8c2','#d9b398','#b78363','#81543d','#4b322b'].map((x,i)=>`<button type="button" style="--skin:${x}" data-a="skin" data-v="${i}" class="swatch" aria-label="Skin tone ${i+1}" aria-pressed="${R.skin.includes(i)}">${R.skin.includes(i)?icon('check'):''}</button>`).join('')}</div><small>You can select two neighboring tones.</small></div><label>Hair color<select data-field="hair">${['Black','Dark brown','Brown','Blonde','Auburn','Grey','Other / dyed'].map(x=>`<option ${R.hair===x?'selected':''}>${x}</option>`).join('')}</select></label>${toggle('covered','Hair covers my forehead','Keep hair away from contact and light positions.')}${disclosure('Why ask about skin and hair?','<p>They can affect contact and light delivery. Device-specific calibration must be validated.</p>')}<button type="submit" class="primary">${R.onboard?'Save & continue':'Save details'}</button></form>`;}
const appearanceQuery=matchMedia('(prefers-color-scheme: dark)');
R.theme=params.get('theme')||(()=>{try{return localStorage.getItem('brainlume-v7-theme')||'system'}catch{return'system'}})();
if(!['light','dark','system'].includes(R.theme))R.theme='system';
groups[4][1].splice(1,0,['appearance','17A','Appearance']);
const mainWithoutAppearance=main;
main=function(){if(R.screen==='appearance')return `<h1>Make it<br>feel like you.</h1><p class="lead">Choose an appearance, or let Brainlume follow your phone.</p><div class="appearance-previews"><div class="mini-preview light"><i></i><span></span><b></b><b></b><small>Light</small></div><div class="mini-preview dark"><i></i><span></span><b></b><b></b><small>Dark</small></div></div><div class="appearance-options" role="group" aria-label="Appearance">${[['light','Light','Soft lavender and clear dark text'],['dark','Dark','Deep blue-violet and cool white text'],['system','Use device setting','Changes with your phone’s appearance']].map(([v,t,d])=>button(`<span><strong>${t}</strong><small>${d}</small></span><i class="radio ${R.theme===v?'selected':''}">${R.theme===v?icon('check'):''}</i>`,'theme',v,'list-button',`aria-pressed="${R.theme===v}"`)).join('')}</div><p class="caption">Your appearance preference is saved on this browser. It applies across the app.</p><section class="language-settings"><h2>App language</h2><div class="segmented">${button('简体中文','language','zh',window.BLI18n?.lang==='zh'?'selected':'',`aria-pressed="${window.BLI18n?.lang==='zh'}"`)}${button('English','language','en',window.BLI18n?.lang!=='zh'?'selected':'',`aria-pressed="${window.BLI18n?.lang!=='zh'}"`)}</div></section>${footer('Back to Device','device')}`;let html=mainWithoutAppearance();if(R.screen==='device')html=html.replace('<div class="section-head"><h2>Your space</h2></div>',`<div class="section-head"><h2>Your space</h2></div>${link(`<span><strong>Appearance & language</strong><small>${R.theme==='system'?'Use device setting':R.theme==='dark'?'Dark':'Light'}</small></span>${icon('arrow')}`,'appearance','list-button')}`);return html;};
function theme(){return R.theme==='system'?(appearanceQuery.matches?'dark':'light'):R.theme;}
function sessionActive(){return R.active&&['measure','light','wear','task','self','result'].includes(R.screen);}
function reviewControls(){return `<p class="review-copy">下面是设计演示控件，不属于 App。所有信号、设备状态与任务均为模拟。</p><label>主题<select data-review="theme">${[['system','跟随系统'],['light','浅色'],['dark','深色']].map(([v,t])=>`<option value="${v}" ${R.theme===v?'selected':''}>${t}</option>`).join('')}</select></label>${['measure','light'].includes(R.screen)?button(R.screen==='measure'?'下一段（演示）':'完成光照（演示）','demo-next','','review-button')+button('模拟蓝牙断开','fault','bluetooth','review-button')+button(R.screen==='measure'?'模拟 CH2 接触不良':'模拟摘下设备','fault','contact','review-button'):''}${R.screen==='light'?['temperature','energy','current'].map(x=>button(`安全停止：${x}`,'safety',x,'review-button')).join(''):''}${R.screen==='wear'?button('模拟接触不良','fit-bad','','review-button'):''}${R.screen==='result'?button('切换无参考／有参考','ref','','review-button')+button('切换证据冲突','conflict','','review-button'):''}${R.screen==='trends'?button('切换空状态','empty','','review-button'):''}${R.screen==='calibration'?`<label>标定结果<select data-review="cal">${[['progress','初测中'],['done','完成待评审'],['uncertain','尚不能确定'],['insufficient','数据不足'],['none','无明显响应']].map(([v,t])=>`<option value="${v}" ${R.cal===v?'selected':''}>${t}</option>`).join('')}</select></label>`:''}`;}
function modalView(){if(!R.modal)return'';let title='End this session?',body='Completed stages stay saved. An incomplete session has no comparison.',actions=button('Keep going','modal-cancel')+button('End safely','end-confirm','','secondary');if(R.modal==='home'){title='Return to Today?';body='Your session will stay paused. Continue it from Today when you are ready.';actions=button('Pause & return','home-confirm')+button('Stay here','modal-cancel','','secondary')}if(R.modal==='delete'){title='Delete preview records?';body='This clears preview sessions and daily sleep context in this browser. It does not affect a real account.';actions=button('Clear preview records','delete-confirm')+button('Cancel','modal-cancel','','secondary')}return `<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${title}"><h2>${title}</h2><p>${body}</p>${actions}</section></div>`;}
function render(preserve=false){const y=document.querySelector('.phone-main')?.scrollTop||0,nav=['home','trends','device'].includes(R.screen);document.documentElement.dataset.theme=theme();document.getElementById('app').innerHTML=`<div class="workspace"><aside class="rail"><a class="rail-brand" href="index.html"><img src="assets/Brainlume-logo-white.png" alt="Brainlume"></a><p class="version">V7 · UE EDITION</p><nav aria-label="Design screens">${groups.map(([g,list])=>`<p class="group-title">${g}</p>${list.map(([id,n,t])=>button(`<small>${n}</small>${t}`,'preview',id,'rail-link '+(R.screen===id?'selected':''))).join('')}`).join('')}</nav><div class="rail-footer"><a href="board.html">设计总览 ↗</a><a href="pages.html">完整页面与状态 ↗</a></div></aside><section class="stage"><div class="stage-toolbar"><span>BRAINLUME / V7 UE / ${theme().toUpperCase()}</span><div>${button('iOS','platform','ios',R.platform==='ios'?'selected':'')}${button('Android','platform','android',R.platform==='android'?'selected':'')}</div></div><article class="phone ${R.platform==='android'?'android':''}" data-screen="${R.screen}" data-theme="${theme()}">${R.screen==='welcome'?'<div class="welcome-waves" data-gradient-waves data-photo-backdrop aria-hidden="true"></div><img class="welcome-portrait" src="assets/welcome-portrait-20261113.png" alt="Model wearing the Brainlume headset">':''}<div class="status"><span>9:41</span><div>${icon('signal')}${icon('wifi')}${icon('battery')}</div></div><header class="app-header">${nav||['measure','light','welcome'].includes(R.screen)?button('<img src="assets/Brainlume-logo-white.png" alt="Brainlume">','logo','','logo','aria-label="Brainlume · Back to Today"'):button(icon('back'),'back','','icon-button','aria-label="Back"')}${nav?button(`<i class="status-dot ${R.connected?'':'offline'}"></i>${R.connected?'Connected':'Offline'}`,'view','device','device-pill','aria-label="Device status"'):`<span class="header-title">${R.screen==='plan'?slug().title:titleOf()}</span>`}</header><main class="phone-main ${nav?'with-nav':''}" tabindex="-1">${sessionRoute()}${main()}</main>${nav?`<nav class="app-nav" aria-label="Main navigation">${[['home','home','Today'],['trends','chart','Trends'],['device','device','Device']].map(([id,i,t])=>button(icon(i)+`<span>${t}</span>`,'view',id,R.screen===id?'selected':'',R.screen===id?'aria-current="page"':'')).join('')}</nav>`:''}${modalView()}${R.toast?`<div class="toast" role="status">${esc(R.toast)}</div>`:''}<div class="home-indicator"></div></article><p class="preview-label">390 × 844 · ${R.platform.toUpperCase()} · INTERACTIVE DESIGN PREVIEW</p></section><aside class="inspector"><p class="version">V7 · 场景与双主题</p><h2>Choose a purpose.<br>Keep the context.</h2><p>新版 UE：三类主要场景、个人较佳表现与建议。日常检查和只照不测有明确入口。</p><p>浅色／深色／跟随系统共用同一套页面与交互。正式算法、任务及质量阈值仍待确认。</p><a href="appearance.html">查看主题对照 ↗</a>${reviewControls()}</aside></div>`;if(preserve)document.querySelector('.phone-main').scrollTop=y;if(R.modal)document.querySelector('.modal button')?.focus();window.BLI18n?.apply(document.getElementById('app'));paintWaves(0);window.BLGradientWaves?.sync();}
function toast(t){R.toast=t;render(true);clearTimeout(R.toastTimer);R.toastTimer=setTimeout(()=>{R.toast='';document.querySelector('.toast')?.remove()},3500);}
function selectScene(v){if(R.active){R.modal='home';render(true);return;}R.scene=v;R.full=v==='fatigue';R.lightOnly=false;R.history=false;go('plan');}
function handle(a,v){if(['end','logo','fault','safety','language'].includes(a))window.speechSynthesis?.cancel();switch(a){case'awake':R.awakeFeeling=['awake','sleepy','unsure'].includes(v)?v:null;render(true);break;case'sleep-save':if(['short','normal','long'].includes(v)){writeDaily(v);render(true)}break;case'sleep-skip':writeDaily(null);render(true);break;case'sleep-edit':R.editSleep=true;render(true);break;case'sleep-cancel':R.editSleep=false;render(true);break;case'wear-waves':R.wearWavePaused=!R.wearWavePaused;if(R.wearWavePaused)R.wearWaveTime=motionSeconds;render(true);break;case'band-eye':R.bandEye=v==='ec'?'ec':'eo';render(true);break;case'language':{const drafts=[...document.querySelectorAll('.phone-main input[name]')].map(el=>[el.name,el.value]);window.BLI18n?.set(v);render(true);for(const [name,value]of drafts){const el=[...document.querySelectorAll('.phone-main input[name]')].find(x=>x.name===name);if(el)el.value=value;}break;}case'view':if(v==='home'&&sessionActive()){R.resume=R.screen;R.modal='home';R.wasPaused=R.paused;R.paused=true;render(true);return;}if(v==='privacy')R.privacyReturn=R.screen;go(v);break;case'preview':R.active=false;R.paused=false;R.modal='';R.contact='good';R.connected=true;R.lightOnly=false;R.history=false;R.elapsed=0;if(v==='complete'){R.beforeDone=R.afterDone=true;R.beforeRating=3;R.afterRating=2;}if(v==='result'){R.beforeDone=true;R.beforeRating=3;}go(v);break;case'scene':selectScene(v);break;case'mode':R.full=v==='true';render();break;case'quick':R.scene='fatigue';R.full=false;R.lightOnly=false;go('plan');break;case'rest':R.lightOnly=true;R.full=false;go('restplan');break;case'rest-duration':R.rest=+v;render(true);break;case'begin':begin();break;case'record':R.elapsed=0;R.paused=false;R.connected=true;R.contact='good';go(R.lightOnly?'light':'measure');if(!R.lightOnly)announcePhase();break;case'phase-cues':R.phaseCues=!R.phaseCues;window.speechSynthesis?.cancel();render(true);break;case'cue-test':announcePhase(true);break;case'pause':R.paused=!R.paused;if(R.paused)window.speechSynthesis?.cancel();render(true);if(!R.paused&&R.screen==='measure')announcePhase();break;case'demo-next':if(R.paused||!R.connected||R.contact==='bad')return;if(R.screen==='measure'){R.elapsed=(Math.floor(R.elapsed/60)+1)*60;if(R.elapsed>=240)measurementDone();else{render(true);announcePhase();}}else if(R.screen==='light')endLight();break;case'rating-save':finishCheck(R.rating);break;case'rating-skip':finishCheck(null);break;case'task-tap':R.taskTaps=Math.min(3,R.taskTaps+1);render(true);break;case'task-done':if(R.taskTaps<3)return;R[R.phase==='after'?'afterTask':'beforeTask']=true;finishCheck(null);break;case'start-light':R.elapsed=0;R.paused=false;go('light');break;case'fault':R.paused=true;if(v==='bluetooth')R.connected=false;else R.contact='bad';go(R.screen==='light'?'held':'invalid');break;case'fix':R.connected=true;R.contact='good';render(true);break;case'fit-bad':R.contact='bad';render(true);break;case'restart':R.elapsed=0;R.paused=false;R.contact='good';R.connected=true;go('wear');break;case'end':R.modal='end';R.wasPaused=R.paused;R.paused=true;render(true);break;case'modal-cancel':R.paused=R.wasPaused??false;R.modal='';render(true);break;case'end-confirm':R.active=false;R.modal='';go('partial');break;case'safety':R.reason=v;R.paused=true;R.active=false;go('safety');break;case'safe-home':R.active=false;go('home');break;case'logo':if(sessionActive()){R.resume=R.screen;R.wasPaused=R.paused;R.paused=true;R.modal='home';render(true);}else go('home');break;case'home-confirm':R.modal='';R.paused=true;go('home');break;case'resume':R.paused=false;go(R.resume||'wear');if(R.screen==='measure')announcePhase();break;case'current-record':R.currentRecord=record();R.history=true;R.historyIndex=R.lightOnly?1:0;go('history');break;case'history':R.currentRecord=null;R.history=true;R.historyIndex=+v;go('history');break;case'range':R.range=+v;render(true);break;case'empty':R.empty=!R.empty;render(true);break;case'ref':R.reference=!R.reference;render(true);break;case'conflict':R.conflict=!R.conflict;render(true);break;case'best-assess':R.scene='cognitive';R.full=false;R.lightOnly=false;go('plan');break;case'rest-start':R.resting=true;R.restElapsed=0;R.restFinished=false;R.dismissed=false;render();break;case'rest-finish':R.resting=false;R.restFinished=true;render();break;case'rest-dismiss':R.dismissed=true;render();break;case'reminders':R.preference=v;toast(v==='off'?'Rest reminders are off in this preview.':'Fewer reminders selected.');break;case'toggle':R[v]=!R[v];render(true);break;case'delete':R.wasPaused=R.paused;R.modal='delete';render();break;case'delete-confirm':R.saved=[];R.dailyDraft=null;try{localStorage.removeItem(contextKey)}catch{}R.modal='';toast('Preview records cleared.');break;case'withdraw':R.research=false;toast('Research preference withdrawn.');break;case'sync':toast('Sync preview only. No data was uploaded.');break;case'export':{const data={demo:true,notice:'Design sample only, not real health data',records:R.saved.length?R.saved.map(withDailyContext):[{scene:'fatigue',beforeRating:3,afterRating:2,example:true}]};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='brainlume-v7-sample.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Sample record exported.');break;}case'device-toggle':R.connected=!R.connected;render(true);break;case'skin':{const i=+v;if(R.skin.includes(i))R.skin=R.skin.filter(n=>n!==i);else if(R.skin.length===1&&Math.abs(R.skin[0]-i)===1)R.skin.push(i);else R.skin=[i];render(true);break;}case'setup':R.onboard=true;go('profile');break;case'activate-next':R.onboard=false;R.connected=true;go('first');break;case'resend':toast('Preview only. No email was sent.');break;case'theme':R.theme=v;try{localStorage.setItem('brainlume-v7-theme',v)}catch{}if(!embedded){const u=new URL(location.href);u.searchParams.set('theme',v);history.replaceState(null,'',u.pathname+u.search);}render(true);break;case'platform':R.platform=v;render(true);break;case'back':go(({appearance:'device',plan:'home',restplan:'home',wear:'plan',self:'measure',task:'measure',features:R.history?'history':'result',result:'home',complete:'home',history:'trends',calibration:'trends',account:'device',profile:R.onboard?'first':'device',privacy:'device',hearing:R.onboard?'profile':'device',email:'welcome',password:'email',verify:'email',forgot:'account',sent:'email',terms:'account'})[R.screen]||'home');break;}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-a]');if(!el)return;e.preventDefault();handle(el.dataset.a,el.dataset.v);});
document.addEventListener('input',e=>{if(e.target.name==='age')R.age=e.target.value;if(e.target.dataset.field==='rating'){R.rating=+e.target.value;document.getElementById('rating-number').textContent=R.rating;}});
document.addEventListener('change',e=>{const field=e.target.dataset.field;if(field)R[field]=e.target.value;const key=e.target.dataset.review;if(key==='theme')handle('theme',e.target.value);if(key==='cal'){R.cal=e.target.value;render();}});
document.addEventListener('submit',e=>{const type=e.target.dataset.form;if(!type)return;e.preventDefault();const f=new FormData(e.target);if(type==='email'){R.email=f.get('email');go('password')}if(type==='password')go('verify');if(type==='reset')go('sent');if(type==='profile'){R.age=f.get('age');if(R.age&&(+R.age<18||+R.age>110)){toast('Enter an age between 18 and 110.');return;}if(!R.skin.length){toast('Choose a skin tone. Two neighboring tones can be selected.');return;}go(R.onboard?'hearing':'device');}});
appearanceQuery.addEventListener('change',()=>{if(R.theme==='system')render(true);});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&['measure','light'].includes(R.screen)){R.paused=true;window.speechSynthesis?.cancel();render(true);}});
document.addEventListener('keydown',e=>{if(!R.modal)return;if(e.key==='Escape'){handle('modal-cancel');return;}if(e.key==='Tab'){const items=[...document.querySelectorAll('.modal button')];if(e.shiftKey&&document.activeElement===items[0]){items.at(-1).focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===items.at(-1)){items[0].focus();e.preventDefault()}}});
function tick(){if(embedded||document.hidden||R.modal)return;if(R.screen==='measure'&&!R.paused&&R.contact==='good'&&R.connected){R.elapsed++;if(R.elapsed>=240){measurementDone();return;}if(R.elapsed%60===0){render(true);announcePhase();return;}const el=document.getElementById('period-clock');if(el)el.textContent=clock(R.elapsed%60);const valid=document.getElementById('usable');if(valid)valid.textContent=window.BLI18n?.t(`${clock(Math.max(0,R.elapsed-Math.ceil(R.elapsed/60)*4))} usable signal · Period ${Math.floor(R.elapsed/60)+1} of 4`)||'';}if(R.screen==='light'&&!R.paused&&R.connected){R.elapsed++;const limit=(R.lightOnly?R.rest:slug().light)*60;if(R.elapsed>=limit){endLight();return;}const el=document.getElementById('light-clock');if(el)el.textContent=clock(limit-R.elapsed);}if(R.screen==='feedback'&&R.resting){R.restElapsed++;const el=document.getElementById('rest-clock');if(el)el.textContent=clock(Math.max(0,180-R.restElapsed));if(R.restElapsed>=180){R.resting=false;R.restFinished=true;render();}}}
setInterval(tick,1000);
let motionSeconds=0,lastPaint=0;const motionPreference=matchMedia('(prefers-reduced-motion: reduce)');
function wave(t,c){return 11*Math.sin((t*8.2+c)*Math.PI*2)+5*Math.sin(t*3.7+c)+3*Math.sin(t*23+c*.6)+2*Math.sin(t*41);}
function paintWaves(t){if(R.screen==='wear'&&R.wearWavePaused)t=R.wearWaveTime||0;for(let c=1;c<=3;c++){const path=document.querySelector(`[data-wave="${c}"]`);if(!path)continue;let d='';for(let i=0;i<=310;i++){const y=35-wave(t+i/78,c)*(.58+c*.07);d+=(i?'L':'M')+i+' '+y.toFixed(2);}path.setAttribute('d',d);const val=document.querySelector(`[data-value="${c}"]`);if(val)val.textContent=!R.connected||R.contact==='bad'?'—':wave(t,c).toFixed(1);}}
let seed=1437;function rnd(){seed=(seed*16807)%2147483647;return(seed-1)/2147483646;}
const photons=Array.from({length:1100},()=>{const z=rnd()*2-1,a=rnd()*Math.PI*2,r=138*(.6+.4*rnd()),p=Math.sqrt(1-z*z);return{x:r*p*Math.cos(a),y:r*z,z:r*p*Math.sin(a),size:.6+rnd()*1.2,h:rnd()};});
function paintOrb(t){document.querySelectorAll('.photon canvas').forEach(canvas=>{const ctx=canvas.getContext('2d');if(!ctx)return;ctx.clearRect(0,0,400,400);const a=t*.13,light=theme()==='light';for(const p of photons){const x=p.x*Math.cos(a)+p.z*Math.sin(a),z=-p.x*Math.sin(a)+p.z*Math.cos(a),scale=400/(400-z),px=200+x*scale,py=200+p.y*scale;ctx.fillStyle=p.h<.16?`rgba(218,104,176,${light?.8:.85})`:p.h<.55?`rgba(169,132,255,${light?.75:.85})`:`rgba(${light?'92,133,222':'149,193,255'},.8)`;ctx.beginPath();ctx.arc(px,py,p.size*scale,0,Math.PI*2);ctx.fill();}});}
function animate(ts){if(ts-lastPaint>42&&!document.hidden){lastPaint=ts;if(!motionPreference.matches&&!R.paused)motionSeconds+=.04;paintWaves(motionSeconds);paintOrb(motionSeconds);}requestAnimationFrame(animate);}
function initPreview(){const st=params.get('state');if(params.get('mode')==='only')R.full=false;if(params.get('mode')==='full')R.full=true;if(params.get('phase')==='after'){R.phase='after';R.beforeDone=true;R.beforeRating=3;}if(st==='awake')R.awakeFeeling='awake';if(st==='sleep-recorded')R.dailyDraft={value:'normal'};if(st==='eyes-closed')R.bandEye='ec';if(st==='fit-failed')R.fitFailed=true;if(['A','B','C'].includes(params.get('sample')))R.bandExample=params.get('sample');if(st==='paused')R.paused=true;if(st==='closed1')R.elapsed=60;if(st==='closed2')R.elapsed=120;if(st==='open2')R.elapsed=180;if(st==='contact'){R.contact='bad';R.paused=true;}if(st==='offline')R.connected=false;if(st==='conflict')R.conflict=true;if(st==='reference')R.reference=true;if(st==='empty')R.empty=true;if(st==='missing')R.beforeRating=null;if(st==='rest'){R.lightOnly=true;R.full=false;}if(st==='resting')R.resting=true;if(st==='dismissed')R.dismissed=true;if(st==='finished')R.restFinished=true;if(st==='onboarding')R.onboard=true;if(['uncertain','insufficient','none','done'].includes(st))R.cal=st;if(st?.startsWith('safety-'))R.reason=st.slice(7);if(R.screen==='result'){R.beforeDone=true;if(st!=='missing')R.beforeRating=3;}if(R.screen==='complete'){R.beforeDone=R.afterDone=true;R.beforeRating=3;R.afterRating=2;R.beforeTask=R.afterTask=R.scene==='cognitive';}if(R.screen==='invalid'){R.contact='bad';R.paused=true;}if(R.screen==='held'){R.beforeDone=true;R.connected=false;R.paused=true;}if(R.screen==='history'){R.history=true;R.historyIndex=st==='excluded'?2:st==='rest'?1:0;}if(!groups.flatMap(g=>g[1]).some(x=>x[0]===R.screen))R.screen='home';}

/* Visual-first UI: short labels, large values, progressively disclosed evidence. */
icons.eye='M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12zM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0';
icons.thermometer='M9 14V5a3 3 0 0 1 6 0v9a5 5 0 1 1-6 0M12 8v9';
icons.calendar='M4 5h16v16H4zM8 2v6m8-6v6M4 10h16';
function visualMetric(i,title,value,unit='',caption=''){return `<div class="visual-metric">${icon(i)}<span>${title}</span><strong>${value}<small>${unit}</small></strong>${caption?`<small>${caption}</small>`:''}</div>`;}
sceneHome=function(){const items=[['fatigue','battery','Fatigue check','20','min + self-report','scene'],['cognitive','brain','Cognitive performance','4','min + task','scene'],['brain','wave','Brain state','4','min + check-in','scene'],['best','trophy','Personal best','','Build your reference','view'],['feedback','smile','Guidance','3','min rest','view']];return `<section class="visual-greeting">${orb()}<p class="home-welcome">Hello, welcome back.</p><h1>How awake<br>do you feel?</h1><div class="awake-checkin" role="group" aria-label="How awake you feel">${[['awake','sun','Awake'],['sleepy','moon','A little sleepy'],['unsure','neutral','Not sure']].map(([v,i,t])=>button(`${icon(i)}<span>${t}</span>`,'awake',v,'awake-option',`aria-pressed="${R.awakeFeeling===v}"`)).join('')}</div>${R.awakeFeeling?'<p class="caption" role="status">Thanks for sharing. Choose any scene below.</p>':''}</section>${R.active?`<section class="resume-card">${button(`${icon('play')} Continue session`,'resume')}</section>`:''}<section class="visual-scenes"><h2>Choose your next step</h2><div class="visual-scene-grid">${items.map(([id,i,t,n,u,a])=>button(`${icon(i)}<strong>${t}</strong><span>${n?`<b>${n}</b>`:''}<small>${u}</small></span>`,a,id,'visual-scene-tile')).join('')}</div></section><div class="ue-shortcuts">${button(`${icon('scan')}<span><strong>Daily check</strong><small>4 min · No light</small></span>`,'quick','','secondary')}${button(`${icon('sun')}<span><strong>Light only</strong><small>10 / 20 / 30 min</small></span>`,'rest','','secondary')}</div>${button(`${icon('book')}<span><strong>Everyday brain states</strong></span>${icon('arrow')}`,'view','learn','learn-entry')}`;};
const detailedResult=resultView;
resultView=function(){const bad=R.contact==='bad',cog=R.scene==='cognitive';return `<h1>${bad?'Signal incomplete':R.conflict?'Sources differ':'Your check, recorded.'}</h1><p class="caption">${slug().title} · Demo</p>${bad?note('Quality is insufficient. No state estimate is generated.','warning'):R.conflict?note('The sources do not agree clearly. No single conclusion is drawn.','warning'):''}<div class="visual-result-metrics">${visualMetric(cog?'brain':R.scene==='brain'?'wave':'battery',cog?'Task score':R.scene==='brain'?'Usable data':'Your fatigue rating',bad||cog?'—':R.scene==='brain'?activeBands().quality:R.beforeRating??'—',cog?'':R.scene==='brain'?'%':'/ 5',cog?'Not available':R.scene==='brain'?'Demo quality':'Self-reported')}</div><div class="visual-status-row"><span>${icon(bad?'info':'check')}${bad?'Not usable':'Usable · Example'}</span><span>${icon('chart')}${R.reference?'Reference available':'No reference yet'}</span></div>${nextStepView()}${disclosure('Record context',recordSummary())}${disclosure(cog?'Your task record':'Your fatigue rating',cog?`${row('Task preview',R.beforeTask?'Completed':'Not completed')}${row('Accuracy','Not available')}${row('Median reaction time','Not available')}${row('CV(RT)','Not available')}${row('Omission rate','Not available')}${row('Scorable trials / difficulty','Not supplied')}${row('Task version','Not supplied')}<p>Demo taps do not generate a cognitive score.</p>`:row('Self-reported',R.beforeRating===null?'Not recorded':R.beforeRating+' / 5'))}${bandDistribution()}${link(`${icon('wave')} View features & quality ${icon('arrow')}`,'features','list-button')}`;};
nextStepView=function(){return `<section class="ue-next-step"><div class="actions">${R.contact==='bad'?button(`${icon('scan')} Check fit & restart`,'restart'):R.full&&R.beforeDone?button(`${icon('sun')} Continue to ${slug().light}-minute light`,'start-light'):link(`${icon('smile')} Review rest suggestions`,'feedback')}${button(`${icon('calendar')} View session record`,'current-record','','secondary')}</div></section>`;};
const activityExample=[0,1,0,2,1,0,3,1,0,1,0,2,0,0,3,1,0,0,1,2,1,0,1,0,2,3,0,1];
function activityHeatmap(){const counts=activityExample.filter(Boolean).length;return `<section class="activity-panel"><div class="section-head"><h2>${icon('calendar')} Activity</h2><small>Demo · 4 weeks</small></div><div class="activity-totals">${visualMetric('calendar','Active days',counts,'/ 28')}${visualMetric('wave','Check days',activityExample.filter(v=>v===1||v===3).length,'')}</div><div class="activity-weekdays" aria-hidden="true">${['M','T','W','T','F','S','S'].map(t=>`<span>${t}</span>`).join('')}</div><div class="activity-grid">${activityExample.map((v,i)=>button(`<span class="sr-only">${i+1}</span>`,'activity-day',String(i),`activity-cell level-${v} ${R.activityDay===i?'selected':''}`,`aria-pressed="${R.activityDay===i}" aria-label="${esc((window.BLI18n?.lang==='zh'?'示例第 '+(i+1)+' 天：':'Example day '+(i+1)+': ')+(['No record','Check','Light only','Check + light'][v]))}"`)).join('')}</div><div class="activity-legend">${[['level-0','No record'],['level-1','Check'],['level-2','Light only'],['level-3','Check + light']].map(([c,t])=>`<span><i class="${c}"></i>${t}</span>`).join('')}</div>${R.activityDay!==undefined?`<div class="activity-selection" role="status">${icon(activityExample[R.activityDay]===2?'sun':'calendar')}<strong>${window.BLI18n?.lang==='zh'?'示例第 '+(R.activityDay+1)+' 天':'Demo day '+(R.activityDay+1)}</strong><span>${['No record','Check recorded','Light only · No EEG','Check + light'][activityExample[R.activityDay]]}</span></div>`:'<p class="caption">Tap a day to view activity.</p>'}<small class="caption">Activity only, not a brain-state score.</small></section>`;}
const detailedMain=main;
main=function(){
 let html=detailedMain();
 if(R.screen==='plan'){
  const t=document.createElement('template');t.innerHTML=html;
  t.content.querySelector('.lead')?.remove();
  t.content.querySelectorAll('.phase-list li').forEach((li,i)=>{li.querySelector('p')?.remove();const marker=document.createElement('span');marker.className='visual-step-icon';marker.innerHTML=icon(R.full&&i===1?'sun':i===2?'check':'scan');li.prepend(marker)});
  html=t.innerHTML;
 }
 if(R.screen==='wear'){
  html=html.replace('<h1>A comfortable fit.<br>A clearer signal.</h1>','<h1>Check your fit.</h1>').replace('<p class="lead">Sit comfortably, relax your forehead and keep hair clear of the contacts.</p>',`<div class="fit-cues"><span>${icon('device')} Adjust fit</span><span>${icon('eye')} Relax your face</span></div>`);
  const t=document.createElement('template');t.innerHTML=html;const sleep=t.content.querySelector('.sleep-context');if(sleep){const wrapper=document.createElement('div');wrapper.innerHTML=disclosure('Last night’s sleep',sleep.outerHTML);sleep.replaceWith(wrapper.firstElementChild)}
  t.content.querySelector('.wear-signals .caption')?.remove();
  const guide=t.content.querySelector('.phase-guidance');if(guide){guide.querySelector('p')?.remove();guide.querySelector('small')?.remove();guide.querySelector('h2')?.remove()}
  html=t.innerHTML;
 }
 if(R.screen==='measure'){
  const t=document.createElement('template');t.innerHTML=html;t.content.querySelector('.session-stage')?.remove();t.content.querySelector('.phase-next')?.remove();
  const note=t.content.querySelector('.signal-caption');if(note&&R.connected&&!R.paused&&R.contact!=='bad')note.remove();html=t.innerHTML;
 }
 if(R.screen==='light'){
  const t=document.createElement('template');t.innerHTML=html;t.content.querySelector('.lead')?.remove();t.content.querySelector('h1').textContent='Time to rest.';
  const checks=t.content.querySelector('.light-checks');checks.innerHTML=`<div class="light-safety-chip">${icon('thermometer')}<span>Temperature</span><strong>Monitoring · Demo</strong></div><div class="light-safety-chip">${icon('bolt')}<span>Energy</span><strong>Within demo limit</strong></div><div class="light-safety-chip">${icon('shield')}<span>Driver current</span><strong>Normal · Demo</strong></div>`;
  const caption=t.content.querySelector('.caption');if(caption){const d=document.createElement('div');d.innerHTML=disclosure('Collection details',caption.outerHTML);caption.replaceWith(d.firstElementChild)}html=t.innerHTML;
 }
 if(R.screen==='trends'&&!R.empty){html=html.replace('<h1>Your patterns,<br>over time.</h1><p class="lead">Compare like with like. Keep the context.</p>','<h1>Your activity.</h1>').replace('<div class="segmented">',activityHeatmap()+'<div class="segmented">');}
 if(R.screen==='complete'){const t=document.createElement('template');t.innerHTML=html;const summary=t.content.querySelector('.record-summary');if(summary){const d=document.createElement('div');d.innerHTML=disclosure('Record context',summary.outerHTML);summary.remove();t.content.append(d.firstElementChild)}if(R.lightOnly){const d=document.createElement('div');d.innerHTML=visualMetric('sun','Light only',R.rest,'min','No EEG collected');t.content.querySelector('.lead')?.after(d.firstElementChild)}html=t.innerHTML;}
 if(R.screen==='self'){html=html.replace('<h1>How does this<br>moment feel?</h1>','<h1>How tired do you feel?</h1>');const t=document.createElement('template');t.innerHTML=html;t.content.querySelector('.lead')?.remove();html=t.innerHTML;}
 if(['device','account','appearance'].includes(R.screen)){const t=document.createElement('template');t.innerHTML=html;t.content.querySelector('.lead')?.remove();const map={profile:'neutral',calibration:'sun',hearing:'sound',account:'neutral',privacy:'shield',appearance:'settings',forgot:'lock'};t.content.querySelectorAll('.list-button,.actions>button').forEach(b=>{if(map[b.dataset.v])b.insertAdjacentHTML('afterbegin',icon(map[b.dataset.v]));});html=t.innerHTML;}
 return html;
};
const detailedHandle=handle;
handle=function(a,v){if(a==='activity-day'){const day=Number(v);if(Number.isInteger(day)&&day>=0&&day<28){R.activityDay=day;render(true);document.querySelector(`[data-a="activity-day"][data-v="${day}"]`)?.focus({preventScroll:true})}return;}detailedHandle(a,v);};

initPreview();render();requestAnimationFrame(animate);
function scienceView(){const items=[['Relaxed / eyes closed','Alpha is often more prominent with eyes closed.','The strongest alpha patterns are usually at the back of the head; forehead electrodes offer a limited view.'],['Focused / alert','Some EEG rhythms are studied alongside alertness and active tasks.','Forehead muscle activity can overlap these frequencies. A single increase does not establish greater focus.'],['Drowsy','Drowsiness changes the meaning of an eyes-closed period.','Sleep and artifacts need to be identified before interpreting a measurement.'],['Cognitive load','Demand can increase during a difficult task.','Higher demand is not automatically a worse state. Behavior and task context matter.'],['Aperiodic features','The EEG spectrum has a broad background as well as rhythmic peaks.','Its physiological interpretation is under study. This prototype does not turn it into a direct balance or health score.']];return `<h1>A little context.<br>A clearer picture.</h1><p class="lead">Research patterns and device capabilities are different things. Keep both in view.</p>${items.map(([t,a,b],i)=>`<article class="card science-card"><small>0${i+1}</small><h2>${t}</h2><p>${a}</p><div class="science-limit"><strong>What this means here</strong><p>${b}</p></div></article>`).join('')}${note('Educational copy adapted from the UE. It does not interpret your personal readings or provide a diagnosis.')}<div class="actions">${link('Back to Today','home')}</div>`;}
